import tempfile
import unittest
from pathlib import Path

from gcode_meta import parse_duration, parse_estimates, read_estimates, safe_gcode_name

ORCA_SAMPLE = """; HEADER_BLOCK_START
; generated by OrcaSlicer
; model printing time: 57m 29s; total estimated time: 1h 3m 12s
; total layer number: 120
; HEADER_BLOCK_END
G28
G1 X10 Y10 ; filament used [g] = 99
; filament used [mm] = 4100.12
; filament used [cm3] = 9.86
; filament used [g] = 12.20
; total filament used [g] = 12.23
; estimated printing time (normal mode) = 1h 2m 3s
"""


class SafeNameTests(unittest.TestCase):
    def test_keeps_only_the_base_name(self):
        self.assertEqual(safe_gcode_name("C:\\models\\cube.gcode"), "cube.gcode")
        self.assertEqual(safe_gcode_name("/tmp/plate 1.GCODE"), "plate 1.GCODE")

    def test_replaces_characters_printers_reject(self):
        self.assertEqual(safe_gcode_name('a"b?c*.gcode'), "a_b_c_.gcode")

    def test_rejects_other_files_and_bad_names(self):
        for bad in ("cube.stl", "", ".gcode", "x" * 200 + ".gcode"):
            with self.subTest(bad=bad[:20]), self.assertRaises(ValueError):
                safe_gcode_name(bad)


class EstimateTests(unittest.TestCase):
    def test_orca_prefers_total_estimates_and_ignores_code_lines(self):
        self.assertEqual(parse_estimates(ORCA_SAMPLE),
                         {"estimate_s": 3792, "estimate_g": 12.23, "estimate_mm": 4100.12})

    def test_prusaslicer_multi_extruder_values_are_summed(self):
        text = "; filament used [g] = 1.50, 2.25\n; estimated printing time (normal mode) = 1d 2h 3m 4s\n"
        self.assertEqual(parse_estimates(text), {"estimate_s": 93784, "estimate_g": 3.75, "estimate_mm": None})

    def test_cura_header(self):
        self.assertEqual(parse_estimates(";FLAVOR:Marlin\n;TIME:1234\n;Filament used: 1.5m\n"),
                         {"estimate_s": 1234, "estimate_g": None, "estimate_mm": 1500.0})

    def test_duration(self):
        self.assertEqual(parse_duration("2h 5m"), 7500)
        self.assertIsNone(parse_duration("unknown"))

    def test_reads_estimates_from_the_tail_of_a_large_file(self):
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / "big.gcode"
            with path.open("w") as fh:
                fh.write(";FLAVOR:Marlin\n")
                fh.write("G1 X1 Y1 E0.1\n" * 200_000)
                fh.write("; total filament used [g] = 42.5\n; estimated printing time (normal mode) = 3h\n")
            self.assertEqual(read_estimates(path), {"estimate_s": 10800, "estimate_g": 42.5, "estimate_mm": None})


if __name__ == "__main__":
    unittest.main()
